// Per klant: vind laatste order, haal product volume eruit (24/48/96),
// bereken depletion date. Als depletion_date - today <= 14 dagen → flag voor reminder.

const depletionDays = { 24: 60, 48: 120, 96: 240 };

const byCustomer = new Map();
for (const item of items) {
  const order = item.json;
  if (!order.customer) continue;
  const cid = String(order.customer.id);
  const existing = byCustomer.get(cid);
  const orderDate = new Date(order.created_at);
  if (!existing || orderDate > existing.lastOrderDate) {
    // Detect volume from line items — product title should contain '24', '48' or '96'
    let volume = 48; // default
    let productName = '';
    for (const li of order.line_items || []) {
      const title = (li.title || li.name || '');
      productName = title;
      const match = title.match(/\b(24|48|96)\b/);
      if (match) { volume = parseInt(match[1], 10); break; }
    }
    byCustomer.set(cid, {
      customer_id: cid,
      customer_email: order.customer.email,
      customer_name: `${order.customer.first_name || ''} ${order.customer.last_name || ''}`.trim(),
      last_order_date: orderDate.toISOString().split('T')[0],
      lastOrderDate: orderDate,
      last_order_product: productName,
      last_order_quantity: volume,
      order_id: order.id
    });
  }
}

const today = new Date();
const flagged = [];
const all = [];
for (const [cid, data] of byCustomer) {
  const days = depletionDays[data.last_order_quantity] || 120;
  const depletion = new Date(data.lastOrderDate);
  depletion.setDate(depletion.getDate() + days);
  const daysUntilDepletion = Math.floor((depletion - today) / (1000 * 60 * 60 * 24));

  const record = {
    ...data,
    estimated_depletion_date: depletion.toISOString().split('T')[0],
    days_until_depletion: daysUntilDepletion,
    needs_reminder: daysUntilDepletion <= 14 && daysUntilDepletion > -7,
    signal_id: `RS-${cid}-${Date.now()}`,
    klaviyo_flow_id_var: `KLAVIYO_REORDER_${data.last_order_quantity}_FLOW_ID`
  };
  all.push({ json: record });
  if (record.needs_reminder) flagged.push(record);
}

return all;

